    Bug 1999349 - Attempt to parse HTTP responses as UTF8 in debug impl. r=edicharry


    If the parsing fails, it still logs as bytes. This is cheap and fast (just an
    extra linear scan for valid codepoints before changing the type of the buffer).

    Differential Revision: https://phabricator.services.mozilla.com/D272312

diff --git a/rust/moz_http/src/response.rs b/rust/moz_http/src/response.rs
index b641bd23d38..3936db92c11 100644
--- a/rust/moz_http/src/response.rs
+++ b/rust/moz_http/src/response.rs
@@ -103,9 +103,13 @@ impl Response {

 impl fmt::Debug for Response {
     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
-        f.debug_struct("Response")
-            .field("status", &self.status())
-            .field("body", &self.body)
-            .finish()
+        let mut f = f.debug_struct("Response");
+        f.field("status", &self.status());
+        if let Ok(ref body) = core::str::from_utf8(&self.body) {
+            f.field("body", body);
+        } else {
+            f.field("body", &self.body);
+        }
+        f.finish()
     }
 }
